; ML620906 boot, generated by tools/gen_template906.py from ML620Q906.asm + the 906 DCL.
; Symbol names were replaced by raw SFR addresses. Names the DCL does not define (inferred):
;   XTM0    = 0F00AH.0  FCON.0 = LOSCEN in the DCL; the 909 boot does the same thing as "ST 81H -> 0F00AH"
;   XTM1    = 0F00AH.1  FCON.1 = LOSCM in the DCL; the 909 boot clears 0F00AH.1 in the same spot
;   KIMASK  = 0F042H    libcw.h KeyboardInMask = 0xF042 (DCL calls it KIMOD); 909 boot writes 0 there
;   KOMASK  = 0F044H    libcw.h KeyboardOutMask = 0xF044 (DCL calls it KOCON); 909 boot writes 80H,0FFH there

type(ML620906)
model large

_$$SP	EQU	0F000h

dw	_$$SP
dw	_START
dw	_BRK
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT
dw	_INT

_BRK:
	mov	psw,	#3
	brk

_INT:
	rti

_START:
	bl	_reset_lr
	mov	r0,	#0
	st	r0,	0F000H
	bl	_init_SFR
	mov	r0,	#0C8h
	mov	r1,	#5
	bl	_timer
	bl	_reset_SFR
	b	_entry

_reset_lr:
	rt

_init_SFR:
	push	lr
	mov	r0,	#31h
	st	r0,	0F00AH
	mov	r0,	#17h
	st	r0,	0F028H

	mov	r0,	#32h
_$init_clock:
	add	r0,	#-1h
	bne	_$init_clock
	lea	0F010H
	mov	er0,	#20h
	st	er0,	[EA+]
	st	r1,	[EA]
	mov	r0,	#7h
	st	r0,	0F03Dh
	mov	r0,	#50h
	mov	r1,	#0
	bl	_timer
	bl	_init_screen
	bl	_init_port1
	bl	_init_port0
	bl	_init_p00
	mov	er0,	#0
	st	r0,	0F042H
	st	er0,	0F046H
	pop	pc

_timer:
	sb	0F00AH.0
	rb	0F00AH.1
	rb	0F028H.3
	di
	mov	er2,	#1
	st	er2,	0F024H
	mov	er2,	#0
	st	er2,	0F022H
	st	er2,	0F014H
	st	r2,	0F016H
	sb	0F010H.5
	st	er0,	0F020H
	mov	r0,	#1
	st	r0,	0F025H
_stop:
	mov	r0,	#50h
	mov	r1,	#0A0h
	st	r0,	0F008H
	st	r1,	0F008H
	mov	r0,	#2
	st	r0,	0F009H
	nop
	nop
	rt

_init_screen:
	mov	r0,	#4
	st	r0,	0F030h
	mov	r0,	#7
	st	r0,	0F033h
	mov	r0,	#9
	st	r0,	0F034h
	mov	r0,	#17h
	st	r0,	0F035h
	mov	er0,	#1
	st	r0,	0F036h
	st	r1,	0F039h
	mov	r0,	#17h
	st	r0,	0F031h
	mov	r0,	#12h
	st	r0,	0F032h
	rt

_init_port1:
	lea	0F220H
	mov	r0,	#0
	mov	r1,	#7Fh
	st	er0,	[EA+]
	st	er0,	[EA+]
	st	r0,	[EA]
	rt

_init_port0:
	lea	0F048H
	mov	er0,	#0
	mov	er2,	#7
	st	er0,	[EA+]
	st	er2,	[EA+]
	st	r2,	[EA]
	rt

_init_p00:
	mov	r0,	#0
	st	r0,	0F041H
	mov	r0,	#80h
	mov	r1,	#0FFh
	st	er0,	0F044H
	rt

_reset_SFR:
	mov	r0,	#1
	st	r0,	0F00AH
	mov	r0,	#4
	st	r0,	0F030h
	mov	r0,	#3
	st	r0,	0F033h
	mov	r0,	#9
	st	r0,	0F034h
	mov	r0,	#17h
	st	r0,	0F035h
	mov	er0,	#1
	st	r0,	0F036h
	st	r1,	0F039h
	mov	r0,	#15h
	st	r0,	0F031h
	rt

_entry:
	;start your program here
	b _main
